export default {
  id: 'local-provider',
  name: 'Local Provider',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'provider',
      provider: {
        id: 'local-response',
        label: 'Local',
        defaultModel: 'local',
        chat: async function* (_req: unknown) {
          yield { type: 'delta' as const, text: 'LOCAL-OK' };
          yield { type: 'usage' as const, input: 1, output: 1 };
          yield { type: 'done' as const };
        },
      },
    });
  },
};

